from dash import dcc,html
import dash_bootstrap_components as dbc
from scalebridge.dashapp.services.generation import campaign_options

def dd(label,id,multi=True): return dbc.Col([html.Label(label),dcc.Dropdown(id=id,multi=multi)],md=4)
def build_layout():
    return html.Div([html.H3('Results'),html.P('Select one generated campaign. Metadata and parquet signals are loaded only for that campaign.'),dcc.Dropdown(id='generation-results-campaign',options=campaign_options(),placeholder='Select a campaign'),html.Div(id='generation-results-metadata',className='mt-3'),dbc.Row([dd('Building type','generation-results-building'),dd('Weather location','generation-results-weather'),dd('Case ID','generation-results-case')],className='g-3'),dbc.Row([dd('Run ID','generation-results-run'),dd('Variable name','generation-results-variable')],className='g-3 mt-1'),dcc.RadioItems(id='generation-results-range-mode',options=[{'label':'Full range','value':'full'},{'label':'Custom range','value':'custom'}],value='full',inline=True,className='mt-3'),dbc.Row([dbc.Col([html.Label('Start datetime'),dbc.Input(id='generation-results-start',type='datetime-local',disabled=True)],md=4),dbc.Col([html.Label('End datetime'),dbc.Input(id='generation-results-end',type='datetime-local',disabled=True)],md=4)],id='generation-results-range-row',className='g-3 mt-1'),dbc.Button('Load and Plot Selected Signals',id='generation-results-plot-button',color='primary',className='mt-3'),dbc.Button('Clear Selection',id='generation-results-clear',outline=True,className='mt-3 ms-2'),html.Div(id='generation-results-message',className='mt-2'),dcc.Graph(id='generation-results-graph'),dcc.Store(id='generation-results-index')],className='page-content-container generation-page')
